assert (H5 : sin (5 * x) = sin (4 * x) * cos x + cos (4 * x) * sin x).
{ replace (5 * x) with (4 * x + x) by ring; apply sin_plus. }
assert (H3' : sin (3 * x) = sin (4 * x) * cos x - cos (4 * x) * sin x).
{ replace (3 * x) with (4 * x - x) by ring; apply sin_minus. }
assert (H2 : sin (2 * x) = 2 * sin x * cos x) by apply sin_2a.
assert (E2 : 2 * sin x * cos (2 * x) = sin (3 * x) - sin x).
