{ rewrite H5, H3'; ring. }
assert (H5' : sin (5 * x) = sin (2 * x)).
{ replace (5 * x) with (PI - 2 * x) by nra; apply sin_PI_x. }
assert (Hprod : 2 * sin x * (cos x - cos (2 * x) - cos (4 * x)) = sin x).
{ rewrite E2, E4, H5'; ring. }
assert (Hcos : cos (3 * x) = - cos (4 * x)).
{ replace (3 * x) with (PI - 4 * x) by nra.
